void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    // Output to screen
    float d = texture(iChannel0, uv, 1.0).r - texture(iChannel0, uv, 0.0).r;
    fragColor = vec4(vec3(step(0.2, d), 0, 0) + vec3(texture(iChannel0, uv, 0.0).r / 5.0, 0, 0), 1);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    float a = step(0.05, uv.x * uv.y);

    // Output to screen
    fragColor = vec4(a, 0, 0, 1.0);
}
